def solve(inputs: dict) -> float:
    M = [[inputs['A'], inputs['B']], [inputs['C'], inputs['D']]]
    result = [[1, 0], [0, 1]]
    for _ in range(int(inputs['K'])):
        acc = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for k in range(2):
                    acc[i][j] = (acc[i][j] + result[i][k] * M[k][j]) % inputs['MOD']
        result = acc
    return (result[0][0] + result[0][1] + result[1][0] + result[1][1]) % inputs['MOD']

